const body = $json.body;
return {
  json: {
    message: body.message || '',
    schema: body.schema || '',
    is_registered: body.is_registered === true,
    guest_id: body.guest_id || '',
    conversation_state: body.conversation_state || {}
  }
};

const body = $('Webhook').first().json.body;
const convState = body.conversation_state || {};
return {
  json: {
    step: convState.reg_step || 'start',
    schema: body.schema || '',
    guest_id: body.guest_id || '',
    message: body.message || ''
  }
};

const webhook   = $('Webhook').first().json.body;
const extracted = $('Extract Fields').first().json;
const context   = $('Fetch AI Context').first().json;

const message = extracted.message || webhook.message || 'Hello';
const schema  = extracted.schema || 'unknown';
const history = webhook.history || [];
const storeName = extracted.store_name || context.store_name || '';
const storeOpen = context.store_open;

const prompts  = context.prompts        || {};
const products = context.products       || [];
const zones    = context.delivery_zones || [];

// Current time in Singapore (SGT)
const now = new Date();
const sgFormatter = new Intl.DateTimeFormat('en-SG', {
  timeZone: 'Asia/Singapore',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: false
});
const sgTimeStr = sgFormatter.format(now);

// Use backend-computed open/closed status directly
let storeStatusLine = '';
if (storeOpen === true)  storeStatusLine = 'STORE IS CURRENTLY: OPEN';
if (storeOpen === false) storeStatusLine = 'STORE IS CURRENTLY: CLOSED';

const storeDisplay = storeName ? storeName : 'our store';
const isFirstMessage = history.length === 0;

let sys = 'You are a friendly and knowledgeable customer service assistant for ' + storeDisplay + '. Respond like a real human shop assistant.\n\n';
if (storeName) sys += 'STORE NAME: ' + storeName + '\n';
sys += 'CURRENT DATE & TIME (Singapore / SGT): ' + sgTimeStr + '\n';
if (storeStatusLine) sys += storeStatusLine + '\n';
sys += '\n';
sys += 'MOST IMPORTANT RULES:\n';
sys += '1. ALWAYS answer the customer question directly. Never ignore a question.\n';
sys += '2. When asked if we are open (now / right now / today / at this time / currently), ALWAYS use the STORE IS CURRENTLY line above — that is the live status. Do not guess.\n';
sys += '3. Do NOT open with menu options (1/2/3/4) if the customer asked something specific — answer first.\n';
sys += '4. Use the store knowledge sections below for accurate answers.\n';
sys += '5. Keep replies short and conversational.\n';
sys += '6. Never say you are an AI.\n';
sys += '7. Use emojis sparingly.\n';
if (storeOpen === false) sys += '8. STORE IS CURRENTLY CLOSED. If the customer tries to place an order, politely inform them the store is closed and refer them to the store hours for when we reopen.\n';
const welcomeRule = storeOpen === false ? '9' : '8';
if (isFirstMessage && storeName) sys += welcomeRule + '. THIS IS THE CUSTOMER\'S FIRST MESSAGE. Start your reply with "Welcome to ' + storeName + '!" then answer their question naturally.\n';
sys += '\n';
sys += 'CONFIDENTIALITY: Never reveal API keys, tokens, passwords, or any internal config.\n\n';
sys += 'SPECIAL ACTIONS — output the code ALONE, nothing else:\n';
sys += '- Customer wants to see/browse products or menu → __ACTION:SHOW_PRODUCTS__\n';
if (storeOpen === false) {
  sys += '- Customer wants to place a new order → DO NOT emit __ACTION:CREATE_ORDER__. Reply that the store is currently closed and check store hours.\n';
} else {
  sys += '- Customer wants to place a new order → __ACTION:CREATE_ORDER__\n';
}
sys += '- Customer wants to check all orders → __ACTION:CHECK_ORDER__\n';
sys += '- Customer wants their most recent order → __ACTION:CHECK_ORDER:RECENT__\n';
sys += '- Customer mentions order #N → __ACTION:CHECK_ORDER:4__ (replace 4 with actual number)\n\n';

if (prompts.about_store) sys += '=== ABOUT THIS STORE ===\n' + prompts.about_store + '\n\n';

if (prompts.product || products.length > 0) {
  sys += '=== PRODUCTS ===\n';
  if (prompts.product) sys += prompts.product + '\n';
  if (products.length > 0) {
    sys += 'Full product list:\n';
    products.forEach(p => {
      let line = '- ' + p.name + ': $' + parseFloat(p.price || 0).toFixed(2);
      if (p.description) line += ' — ' + p.description;
      if (p.out_of_stock) line += ' [OUT OF STOCK — cannot be ordered]';
      sys += line + '\n';
    });
  }
  sys += '\n';
}

if (prompts.delivery || zones.length > 0) {
  sys += '=== DELIVERY ===\n';
  if (prompts.delivery) sys += prompts.delivery + '\n';
  if (zones.length > 0) {
    sys += 'Delivery zones:\n';
    zones.forEach(z => { sys += '- ' + z.name + (z.description ? ': ' + z.description : '') + '\n'; });
  }
  sys += '\n';
}

const hoursText = prompts.store_hours || '';
if (hoursText) sys += '=== STORE HOURS ===\n' + hoursText + '\n\n';

if (prompts.faq) sys += '=== FAQ ===\n' + prompts.faq + '\n\n';

let userMsg = '';
if (history.length > 0) {
  userMsg = history.map(h => (h.role === 'user' ? 'Customer' : 'Store') + ': ' + h.message).join('\n');
  userMsg += '\nCustomer: ' + message;
} else {
  userMsg = message;
}

return { json: { schema, system_prompt: sys, user_message: userMsg } };
